-- Create "quotes_authors" table
CREATE TABLE "quotes_authors" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying NOT NULL, "node_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "quotes_authors_nodes_node" FOREIGN KEY ("node_id") REFERENCES "nodes" ("id") ON DELETE SET NULL);
-- Create index "quotes_authors_name_key" to table: "quotes_authors"
CREATE UNIQUE INDEX "quotes_authors_name_key" ON "quotes_authors" ("name");
-- Create index "quoteauthor_node_id" to table: "quotes_authors"
CREATE INDEX "quoteauthor_node_id" ON "quotes_authors" ("node_id");
-- Create "quotes" table
CREATE TABLE "quotes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "text" text NOT NULL, "citation" text NULL, "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "author_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "quotes_quotes_authors_author" FOREIGN KEY ("author_id") REFERENCES "quotes_authors" ("id") ON DELETE SET NULL);
-- Create index "quote_author_id" to table: "quotes"
CREATE INDEX "quote_author_id" ON "quotes" ("author_id");
